do $$ begin
  if (select count(*) from public.handicap_calculation_runs) <> 3 then raise exception 'Phase 105 run count mismatch'; end if;
  if (select count(*) from public.handicap_source_provenance) <> 27944 then raise exception 'Phase 105 modified provenance'; end if;
  if (select count(*) from public.handicap_rating_snapshots) <> 410 then raise exception 'Phase 105 rating count mismatch'; end if;
  if (select count(*) from public.handicap_index_snapshots) <> 157 then raise exception 'Phase 105 index count mismatch'; end if;
  if (select count(*) from public.handicap_calculation_runs where id='3973f8e7-f2c9-5d05-bdb7-e49810713612'::uuid and status='DRAFT' and publication_eligibility='QUARANTINED') <> 1 then raise exception 'Phase 105 run not quarantined'; end if;
  if (select count(*) from public.handicap_rating_snapshots where calculation_run_id='3973f8e7-f2c9-5d05-bdb7-e49810713612'::uuid and publication_status='UNPUBLISHED' and effective_from is null) <> 72 then raise exception 'Phase 105 ratings not unpublished'; end if;
  if (select count(*) from public.handicap_index_snapshots where calculation_run_id='3973f8e7-f2c9-5d05-bdb7-e49810713612'::uuid and publication_status='UNPUBLISHED' and chronology_confidence='OFFICIAL_KWT_SEQUENCE') <> 157 then raise exception 'Phase 105 indexes not unpublished'; end if;
  if exists (select 1 from public.handicap_index_snapshots i, lateral unnest(i.source_round_ids) refs(source_ref) where i.calculation_run_id='3973f8e7-f2c9-5d05-bdb7-e49810713612'::uuid and source_ref like 'THE_WEEKLY|%') then raise exception 'Weekly source entered personal indexes'; end if;
  if exists (select 1 from public.handicap_rating_snapshots s, lateral unnest(s.source_evidence_refs) refs(source_ref) left join public.handicap_source_provenance p on p.source_fingerprint=refs.source_ref where s.calculation_run_id='3973f8e7-f2c9-5d05-bdb7-e49810713612'::uuid and p.id is null) then raise exception 'rating provenance reference missing'; end if;
  if exists (select 1 from public.handicap_index_snapshots i, lateral unnest(i.rating_snapshot_ids) refs(rating_id) left join public.handicap_rating_snapshots s on s.id=refs.rating_id where i.calculation_run_id='3973f8e7-f2c9-5d05-bdb7-e49810713612'::uuid and s.id is null) then raise exception 'index rating reference missing'; end if;
  if (select count(*) from public.handicap_publishable_rating_snapshots) <> 0 then raise exception 'ratings unexpectedly publishable'; end if;
  if (select count(*) from public.handicap_publishable_index_snapshots) <> 0 then raise exception 'indexes unexpectedly publishable'; end if;
end $$;
commit;
